const response = $input.item.json;
let rawContent = '';
if (response.choices && response.choices[0] && response.choices[0].message) {
  rawContent = response.choices[0].message.content;
} else {
  rawContent = JSON.stringify(response);
}

let classification = {
  is_emergency: false,
  emergency_type: 'other',
  confidence: 0.5,
  reason: 'Default parse'
};

try {
  classification = JSON.parse(rawContent.replace(/```json|```/g, '').trim());
} catch (e) {
  // Heuristic parse fallback
  const isEm = /flood|fire|urgent|trapped|medical|casualty/i.test($node['Normalize Emergency Schema'].json.message);
  classification = { is_emergency: isEm, emergency_type: 'flood', confidence: 0.8, reason: 'Fallback heuristic parse' };
}

return {
  ...$node['Normalize Emergency Schema'].json,
  classification: classification,
  is_emergency: Boolean(classification.is_emergency)
};
